import sys

capacidade = 4
dados = [None] * capacidade
inicio = 0
fim = 0
tamanho = 0

def inserir(item):
    global fim, tamanho
    if tamanho == capacidade:
        return "fila cheia"
    dados[fim] = item
    fim = (fim + 1) % capacidade
    tamanho += 1

def remover():
    global inicio, tamanho
    if inicio == fim:
        return "fila vazia"
    item = dados[inicio]
    inicio = (inicio + 1) % capacidade
    tamanho -= 1
    return item

for linha in sys.stdin:
    partes = linha.strip().split(maxsplit=1)
    if not partes:
        continue
    op = partes[0].upper()
    if op == "INSERIR" and len(partes) == 2:
        res = inserir(partes[1])
        if res is not None:
            print(res)
    elif op == "REMOVER":
        print(remover())
    elif op == "ESTADO":
        print(inicio, fim, tamanho)
    elif op == "DRENAR":
        saidas = []
        while tamanho > 0:
            saidas.append(str(remover()))
        print(" ".join(saidas) if saidas else "vazia")

